import{_ as i,a0 as l,w as o,s as p,ao as c,I as d,x as a,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"通过示例来学习 Bash base64 的编码和解码 | LCTT x X-CMD","titleTemplate":false,"description":"通过示例来学习 Bash base64 的编码和解码 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过示例来学习 Bash base64 的编码和解码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过示例来学习 Bash base64 的编码和解码 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221013 Learn Bash base64 Encode and Decode With Examples","title":"通过示例来学习 Bash base64 的编码和解码","tag":"202210","desc":""},"relativePath":"202210/20221013 Learn Bash base64 Encode and Decode With Examples.md","filePath":"[post].md"}'),r={name:"202210/20221013 Learn Bash base64 Encode and Decode With Examples.md"};function h(b,e,g,u,m,k){const s=l("Link");return o(),p("div",null,[e[18]||(e[18]=c(`<h1 id="通过示例来学习-bash-base64-的编码和解码" tabindex="-1">通过示例来学习 Bash base64 的编码和解码 <a class="header-anchor" href="#通过示例来学习-bash-base64-的编码和解码" aria-label="Permalink to “通过示例来学习 Bash base64 的编码和解码”">​</a></h1><blockquote><p>你想了解 Base64 编码和解码的方法吗？在本教程中，我们使用 Bash shell 脚本和各种示例解释了 Base64 编码和解码步骤。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202210/29/163350mde5lll86j6lspln.jpg" alt=""></p><p>Base64 编码方法可以将二进制数据转换为文本，如此编码数据可以在任何通信媒介进行传输。这种编码方法主要用于电子邮件加密的过程。</p><p>总体而言，Base64 编码方法是一种二进制到文本的编码方案，以 ASCII 字符串格式表示 8 字节的二进制数据。使用这种编码方法在各种媒介之间传输数据时有几个优势，尤其是对于那些能可靠地支持文本内容的媒介。因此，Base64 编码方法在万维网上被广泛使用。这种编码方案最常用于电子邮件附件的编码上。</p><p>根据 Base64 编码表，二进制数据可以经 Base64 编码后可以转换为 64 个不同的 ASCII 字符，包含大写字母 <code>A</code> 到 <code>Z</code>，小写字母 <code>a</code> 到 <code>z</code>，数字 <code>0</code> 到 <code>9</code>，以及符号 <code>+</code> 和 <code>/</code>，这些字符在传输和打印上十分便捷。</p><p>这 64 个 ASCII 字符代表着从 <code>000000</code> 到 <code>111111</code> 的二进制值。每个非末尾的 Base64 编码字符恰好代表 6 位二进制值。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/Base64-Index-Table.png" alt="Base64 Index Table"></p><h3 id="bash-base64-的编码和解码" tabindex="-1">Bash base64 的编码和解码 <a class="header-anchor" href="#bash-base64-的编码和解码" aria-label="Permalink to “Bash base64 的编码和解码”">​</a></h3><h4 id="句法" tabindex="-1">句法 <a class="header-anchor" href="#句法" aria-label="Permalink to “句法”">​</a></h4><p>在我们提供示例之前，首先介绍 Base64 的基本语法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>base64 [OPTIONs] [INFILE] [OUTFILE]</span></span></code></pre></div><ul><li>选项（<code>Option</code>）：参照下面的表格，你可以提供任何的选项或组合多个选项。</li><li>输入（<code>INFILE</code>）：你可以从标准输入（如命令行）或文件中输入。</li><li>输出（<code>OUTFILE</code>）：你可以将输出重定向到标准输出，如终端或文件中。</li></ul><div class="table-wrap"><table><thead><tr><th style="text-align:left;">选项</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-e</code> 或者 <code>--encode</code></td><td style="text-align:left;">此选项用于对标准输入的数据或从文件中读入的数据进行编码。这是默认选项。</td></tr><tr><td style="text-align:left;"><code>-d</code> 或者 <code>--decode</code></td><td style="text-align:left;">此选项用于对标准输入的数据或从文件中读入的已 Base64 编码数据进行解码。</td></tr><tr><td style="text-align:left;"><code>-n</code> 或者 <code>--noerrcheck</code></td><td style="text-align:left;">默认情况下，Base64 在解码数据时，会自动检查是否有错误。你可以使用该选项在解码时忽略检查。</td></tr><tr><td style="text-align:left;"><code>-i</code> 或 <code>--ignore-garbage</code></td><td style="text-align:left;">此选项用于在解码时忽略非字母字符。</td></tr><tr><td style="text-align:left;"><code>-u</code> 或者 <code>--help</code></td><td style="text-align:left;">此选项用于获取有关使用此命令的信息。</td></tr></tbody></table></div><h4 id="示例-1-基本编码" tabindex="-1">示例 1：基本编码 <a class="header-anchor" href="#示例-1-基本编码" aria-label="Permalink to “示例 1：基本编码”">​</a></h4><p>在 Linux 中，默认已安装好 Base64 软件包。因此，你可以轻松地从命令行使用 Base64。要对一个字符串或文本进行编码，你可以通过管道将其传递到 <code>base64</code> 命令，并获取待编码的文本。在下面的示例中，对字符串 <code>debugpoint.com</code> 进行了 Base64 编码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;debugpoint.com&quot; | base64</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/bash-base64-encode-and-decode-example-1.jpg" alt="bash base64 encode and decode - example 1"></p><p>结果是经过 Base64 编码后的字符串。</p><h4 id="解释" tabindex="-1">解释 <a class="header-anchor" href="#解释" aria-label="Permalink to “解释”">​</a></h4><p>Base64 编码方法使用下面的几个步骤来转换输入的数据。首先，每个输入字符转换为 8 位二进制值，接着，二进制字符串拆分为一组组 6 位的二进制值，然后，每个 6 位的二进制值被转换为十进制值。</p><p>最后，每个十进制值都通过 Base64 编码索引表转换为 Base64 字符。</p><p>在上面的示例中，第一个字符 <code>d</code> 被转换为二进制 <code>01100100</code>。前 6 位是 <code>011001</code>，转换为十进制是 <code>25</code>。<code>25</code> 在 Base64 编码索引表中对应着 <code>Z</code>。整个输入的文本流都像如此编码。请参阅以下编码过程的示例。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/Base64-Encode-and-Decode-inner-working.png" alt="Base64 Encode and Decode – inner working"></p><h4 id="示例-2-基本解码" tabindex="-1">示例 2：基本解码 <a class="header-anchor" href="#示例-2-基本解码" aria-label="Permalink to “示例 2：基本解码”">​</a></h4><p>要解码字符串，需要将编码值传递给 <code>base64</code> 命令，选项为 <code>--decode</code>，它将输出你之前输入的字符串。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/bash-base64-encode-and-decode-example-2-decode-the-same-example.jpg" alt="bash base64 encode and decode - example 2 (decode the same example)"></p><h4 id="示例-3-对文本文件进行编码" tabindex="-1">示例 3：对文本文件进行编码 <a class="header-anchor" href="#示例-3-对文本文件进行编码" aria-label="Permalink to “示例 3：对文本文件进行编码”">​</a></h4><p>示例 1 中的同一命令也可用于编码文本文件，并将输出重定向到另一个文本文件。方法如下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>base64 example3.txt &gt; example3-encoded.txt</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/Encode-a-text-file.png" alt="Encode a text file"></p><h4 id="示例-4-对文本文件进行解码" tabindex="-1">示例 4：对文本文件进行解码 <a class="header-anchor" href="#示例-4-对文本文件进行解码" aria-label="Permalink to “示例 4：对文本文件进行解码”">​</a></h4><p>要解码使用 Base64 编码的文本文件，只需使用 <code>--decode</code> 或 <code>-d</code> 选项，并传递文本文件名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>base64 -d example3-encoded.txt</span></span></code></pre></div><h4 id="示例-5-对用户输入的数据进行编码" tabindex="-1">示例 5：对用户输入的数据进行编码 <a class="header-anchor" href="#示例-5-对用户输入的数据进行编码" aria-label="Permalink to “示例 5：对用户输入的数据进行编码”">​</a></h4><p>使用 Bash shell 编程，你可以通过终端接收用户的输入，并对其进行 Base64 编码。你需要先编写一个简单的 shell 脚本，并在授予可执行权限后执行。</p><p>以下就是一个简单的示例，它从用户那里获得输入，然后进行 Base64 编码，最终显示编码的字符串。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#Sample program to take input, encode to base64 and display on terminal</span></span>
<span class="line"><span>#Example by www.debugpoint.com</span></span>
<span class="line"><span>echo &quot;Enter text for encoding to base64:&quot;</span></span>
<span class="line"><span>read input_text</span></span>
<span class="line"><span>output_text=\`echo -n $input_text | base64\`</span></span>
<span class="line"><span>echo &quot;The Base64 Encoded text is: $output_text&quot;</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/Custom-input-base64-encode-and-decode-using-script.png" alt="Custom input - base64 encode and decode using script"></p><h4 id="示例-6-用-base64-进行简单的身份认证" tabindex="-1">示例 6：用 Base64 进行简单的身份认证 <a class="header-anchor" href="#示例-6-用-base64-进行简单的身份认证" aria-label="Permalink to “示例 6：用 Base64 进行简单的身份认证”">​</a></h4><p>你可以运用上述的编码和解码方法，实现一个简单的身份验证系统。你可以让用户输入密码或密码，然后将密码存储在文件中。或者进行实时比较。</p><p>如果存储的编码字符串与用户输入的文本再编码的字符串相匹配，则用户可以通过验证。虽然这是一种检查身份验证的很简单的方法，但有时这对一些简单的业务案例很有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#Sample program to take input, encode to base64 and display on terminal</span></span>
<span class="line"><span>#Example by www.debugpoint.com</span></span>
<span class="line"><span>echo &quot;Type your password&quot;</span></span>
<span class="line"><span>read pwd1</span></span>
<span class="line"><span>decoded_text=\`echo &#39;U2lsZW5jZSBpcyBnb2xkZW4h&#39; | base64 --decode\`</span></span>
<span class="line"><span>if [[ $pwd1 == $decoded_text ]]</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    echo &quot;You are a valid user.&quot;</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    echo &quot;You are NOT a valid user.&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/11/A-Simple-Authentication-using-bash-base64.png" alt="A Simple Authentication using bash base64"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>`,45)),d("p",null,[e[1]||(e[1]=a("我希望你能通过这些示例，学会 ",-1)),t(s,{href:"https://linux.die.net/man/1/base64"},{default:n(()=>[...e[0]||(e[0]=[a("Base64",-1)])]),_:1}),e[2]||(e[2]=a(" 编码和解码的基础知识。此外，你也了解到 Base64 的内部编码方式。如果这对你很有帮助，或你还需要有关此主题的其他教程，请在下面的评论区中告诉我吧。",-1))]),e[19]||(e[19]=d("hr",null,null,-1)),d("p",null,[e[4]||(e[4]=a("via: ",-1)),t(s,{href:"https://www.debugpoint.com/bash-base64-encode-decode/"},{default:n(()=>[...e[3]||(e[3]=[a("https://www.debugpoint.com/bash-base64-encode-decode/",-1)])]),_:1})]),d("p",null,[e[9]||(e[9]=a("作者：",-1)),t(s,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...e[5]||(e[5]=[a("Arindam",-1)])]),_:1}),e[10]||(e[10]=a(" 选题：",-1)),t(s,{href:"https://github.com/lkxed"},{default:n(()=>[...e[6]||(e[6]=[a("lkxed",-1)])]),_:1}),e[11]||(e[11]=a(" 译者：",-1)),t(s,{href:"https://github.com/chai001125"},{default:n(()=>[...e[7]||(e[7]=[a("chai001125",-1)])]),_:1}),e[12]||(e[12]=a(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[8]||(e[8]=[a("wxy",-1)])]),_:1})]),d("p",null,[e[15]||(e[15]=a("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[13]||(e[13]=[a("LCTT",-1)])]),_:1}),e[16]||(e[16]=a(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:n(()=>[...e[14]||(e[14]=[a("Linux中国",-1)])]),_:1}),e[17]||(e[17]=a(" 荣誉推出",-1))])])}const B=i(r,[["render",h]]);export{w as __pageData,B as default};
